function countPermutations(complexity) {
  const MOD = 1e9 + 7;
  let ways = 1;
  for (let i = 1; i < complexity.length; i++) {
    if (complexity[i] <= complexity[0]) {
      return 0;
    }
    ways = (ways * i) % MOD;
  }
  return ways;
}

