function countPermutations(complexity) {
  // Build every unlocking order one computer at a time and count the complete ones.
  const n = complexity.length;
  const unlocked = new Array(n).fill(false);
  unlocked[0] = true;
  const extend = (done) => {
    if (done === n) return 1;
    let total = 0;
    for (let i = 1; i < n; i++) {
      if (unlocked[i]) continue;
      let opener = false;
      for (let j = 0; j < i; j++) if (unlocked[j] && complexity[j] < complexity[i]) opener = true;
      if (!opener) continue;
      unlocked[i] = true;
      total += extend(done + 1);
      unlocked[i] = false;
    }
    return total;
  };
  return extend(1) % 1000000007;
}

