function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? int(1800, 2000) : int(2, 8);
  const top = size === 'large' ? 1000000000 : 8;
  const complexity = Array.from({ length: n }, () => int(2, top));
  const shape = rand();
  if (shape < 0.55) {
    // Computer 0 is strictly the simplest, so every order of the rest works.
    complexity[0] = 1;
  } else if (shape < 0.8) {
    // Computer 0 ties the simplest of the others, so nothing works.
    complexity[0] = Math.min(...complexity.slice(1));
  }
  return [complexity];
}
